        "Ar atrašanās vietu in bieži tulko kā iekšā vai -ā: in Berlin = Berlīnē.",
        "Ar kustību in nozīmē uz iekšieni: ins Kino = uz kino.",
        "Latviski tulkojums mainās pēc konteksta."
