        "Runājot par vietu, situāciju vai personu, sicher = drošs (ein sicherer Ort = droša vieta).",
        "Kā apstiprinājums vai pārliecība teikumā, sicher = noteikti/protams (Das ist sicher wahr. = Tas noteikti ir taisnība.).",
